def indexBox (grid : ℕ) (lower : BoxKey) : Set (Fin 5 → ℝ) :=
  {t | ∀ i, (lower i : ℝ) / grid ≤ t i ∧
    t i < ((lower i : ℝ) + 1) / grid}
